-- ZUNE MARKET additive feature tables. Existing wishlist/review/support/dispute tables are reused.
create table if not exists public.product_comparisons(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,product_id));
create table if not exists public.price_drop_alerts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,target_price numeric(14,2) not null check(target_price>0),active boolean not null default true,last_notified_price numeric(14,2),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product_id));
create table if not exists public.zune_reward_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,points integer not null check(points<>0),entry_type text not null check(entry_type in('earned','redeemed','adjustment','referral')),description text not null,reference_id uuid,created_at timestamptz not null default now());
create table if not exists public.zune_referral_codes(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,code text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.zune_referrals(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references auth.users(id) on delete cascade,referred_user_id uuid not null unique references auth.users(id) on delete cascade,referral_code text not null references public.zune_referral_codes(code),status text not null default 'pending' check(status in('pending','qualified','rewarded','rejected')),created_at timestamptz not null default now(),qualified_at timestamptz);
create index if not exists product_comparisons_user_idx on public.product_comparisons(user_id,created_at desc);
create index if not exists price_drop_alerts_active_idx on public.price_drop_alerts(user_id,active) where active;
create index if not exists zune_reward_ledger_user_idx on public.zune_reward_ledger(user_id,created_at desc);
alter table public.product_comparisons enable row level security;alter table public.price_drop_alerts enable row level security;alter table public.zune_reward_ledger enable row level security;alter table public.zune_referral_codes enable row level security;alter table public.zune_referrals enable row level security;
drop policy if exists product_comparisons_owner_all on public.product_comparisons;create policy product_comparisons_owner_all on public.product_comparisons for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists price_drop_alerts_owner_all on public.price_drop_alerts;create policy price_drop_alerts_owner_all on public.price_drop_alerts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists zune_reward_ledger_owner_read on public.zune_reward_ledger;create policy zune_reward_ledger_owner_read on public.zune_reward_ledger for select to authenticated using(user_id=auth.uid());
drop policy if exists zune_referral_codes_owner_all on public.zune_referral_codes;create policy zune_referral_codes_owner_all on public.zune_referral_codes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
drop policy if exists zune_referrals_participant_read on public.zune_referrals;create policy zune_referrals_participant_read on public.zune_referrals for select to authenticated using(referrer_id=auth.uid() or referred_user_id=auth.uid());
grant select,insert,update,delete on public.product_comparisons,public.price_drop_alerts,public.zune_referral_codes to authenticated;grant select on public.zune_reward_ledger,public.zune_referrals to authenticated;